function peelLayers(root: TreeNode | null): number[][] {
  const layers: number[][] = [];
  // removes the leaves under node into round, returns what is left of node
  const peel = (node: TreeNode | null, round: number[]): TreeNode | null => {
    if (!node) return null;
    if (!node.left && !node.right) { round.push(node.val); return null; }
    node.left = peel(node.left, round);
    node.right = peel(node.right, round);
    return node;
  };
  while (root) {
    const round: number[] = [];
    root = peel(root, round);
    layers.push(round);
  }
  return layers;
}

