class Solution:
    def peelLayers(self, root: Optional[TreeNode]) -> List[List[int]]:
        def peel(node, round_):
            if not node:
                return None
            if not node.left and not node.right:
                round_.append(node.val)
                return None
            node.left = peel(node.left, round_)
            node.right = peel(node.right, round_)
            return node

        layers = []
        while root:
            round_ = []
            root = peel(root, round_)
            layers.append(round_)
        return layers

