function peelLayers(root: TreeNode | null): number[][] {
  const layers: number[][] = [];
  const height = (node: TreeNode | null): number => {
    if (!node) return -1;
    const h = 1 + Math.max(height(node.left), height(node.right));
    if (layers.length === h) layers.push([]);
    layers[h].push(node.val);
    return h;
  };
  height(root);
  return layers;
}

